const $=id=>document.getElementById(id), net=NETWORK, fmt=(v,n=2)=>Number(v).toLocaleString('en-US',{minimumFractionDigits:n,maximumFractionDigits:n});
let cfg={kv:11,amps:350,pf:.8,sourcePU:1},bank='180075',selected=bank,before,after,view='compare';
const merc=([lon,lat])=>[lon/360*256,(1-Math.log(Math.tan(lat*Math.PI/180)+1/Math.cos(lat*Math.PI/180))/Math.PI)/2*256];
const nodeXY=Object.fromEntries(Object.entries(net.nodes).map(([n,d])=>[n,merc(d.coords)]));
const xy=Object.values(nodeXY), xs=xy.map(p=>p[0]),ys=xy.map(p=>p[1]);
const minX=Math.min(...xs),minY=Math.min(...ys),w=Math.max(...xs)-minX,h=Math.max(...ys)-minY,extent=Math.max(w,h)*1.3;
const initial={x:(minX+Math.max(...xs)-extent)/2,y:(minY+Math.max(...ys)-extent)/2,size:extent};let camera={...initial};
$('bankNode').innerHTML=Object.keys(net.nodes).filter(n=>n!==net.source).map(n=>`<option value="${n}">${n}${net.nodes[n].inferred?' · approximate':''}</option>`).join('');$('bankNode').value=bank;
$('methodText').textContent=`${net.metadata.electricalSections} electrical sections, ${Object.keys(net.nodes).length} nodes, ${net.metadata.surveyPathSections} survey-path matches. Sources: ${net.metadata.mapSource}; ${net.metadata.surveySource}; ${net.metadata.sourceWorkbook}. ${net.metadata.mappingNote}`;
function color(v,metric){if(metric==='loading')return v>1?'#d04645':v>.8?'#d18b1e':'#128b79';if(metric==='gain')return v<-.1?'#b63f55':v<1?'#83989d':v<20?'#4fb8c4':v<50?'#1476aa':'#5545ac';return v<.95?'#cf4648':v<.97?'#d38c22':v<.99?'#39a5b4':v<=1.05?'#087e67':'#a447a5'}
function run(){try{before=solveNetwork(net,cfg,null,0);after=solveNetwork(net,cfg,bank,$('bankOn').checked?Number($('kvar').value):0);render()}catch(e){$('alerts').textContent=e.message}}
function stat(title,value,unit,old,delta){return `<div class="stat"><small>${title}</small><strong>${value} <small style="display:inline">${unit}</small></strong><div class="delta">${delta}</div><div class="previous">Before ${old}</div></div>`}
function render(){
 const applied=$('bankOn').checked?Number($('kvar').value):0,saved=before.loss-after.loss;
 $('sizeText').textContent=fmt(Number($('kvar').value),0)+' kVAr';$('afterTitle').textContent=applied?fmt(applied,0)+' kVAr ON':'Bank OFF';$('bankOn').nextElementSibling.textContent=$('bankOn').checked?'ON':'OFF';
 $('stats').innerHTML=stat('Lowest node voltage',fmt(after.minV*11,3),'kV',fmt(before.minV*11,3)+' kV',`${after.minV>=before.minV?'+':''}${fmt((after.minV-before.minV)*11000,1)} V · ${fmt(after.minV,4)} pu`)+stat('HT conductor loss',fmt(after.loss,2),'kW',fmt(before.loss,2)+' kW',`${fmt(saved,2)} kW ${saved>=0?'saved':'extra loss'}`)+stat('Feeder head current',fmt(after.headCurrent,1),'A',fmt(before.headCurrent,1)+' A',`${fmt(before.headCurrent-after.headCurrent,1)} A reduction`)+stat('Source power factor',fmt(after.headPF,3),'',fmt(before.headPF,3),`${fmt(after.headQ,0)} kVAr · ${after.headQ<0?'leading':'lagging'}`);
 const notices=[];if(after.overloads)notices.push(`${after.overloads} conductor sections remain above 100% loading.`);if(after.minV<.95)notices.push('Some nodes are below the 0.95 pu demo band.');if(after.maxV>1.05)notices.push('Some nodes exceed the 1.05 pu demo band.');if(after.headQ<0)notices.push('Source reactive flow is leading: bank output exceeds feeder reactive demand.');if(saved<-.01)notices.push('This bank placement increases HT conductor losses.');
 $('alerts').innerHTML=`<div class="notice ${notices.length?'':'good'}">${notices.length?notices.join(' '):'Scenario is within the demo voltage and thermal bands, with lagging source reactive flow.'} <span>Estimated results · ${applied?fmt(applied,0)+' kVAr at node '+bank:'capacitor OFF'}.</span></div>`;
 $('beforePanel').classList.toggle('hidden',view==='after');$('afterPanel').classList.toggle('hidden',view==='before');$('maps').classList.toggle('single',view!=='compare');
 renderMap($('beforeMap'),before,false);renderMap($('afterMap'),after,true);legend();detail();profile();
}
function tileMarkup(){if(!$('basemap').checked)return '';const z=Math.min(18,Math.max(13,Math.floor(Math.log2(1/camera.size*512)))),scale=2**z,step=256/scale;let s='';let count=0;
 for(let x=Math.floor(camera.x/step);x<=Math.floor((camera.x+camera.size)/step);x++)for(let y=Math.floor(camera.y/step);y<=Math.floor((camera.y+camera.size)/step);y++){if(count++>100)break;s+=`<image href="https://tile.openstreetmap.org/${z}/${x}/${y}.png" x="${x*step}" y="${y*step}" width="${step}" height="${step}" opacity="0.7"/>`;}return s;}
function renderMap(svg,result,isAfter){
 svg.setAttribute('viewBox',`${camera.x} ${camera.y} ${camera.size} ${camera.size}`);const metric=$('metric').value,scale=camera.size/450,r=3.5*scale;
 const path=cs=>cs.map((p,i)=>{const q=merc(p);return (i?'L':'M')+q.join(' ')}).join(' ');
 let s=tileMarkup();if(!$('basemap').checked){const grid=initial.size/8;for(let i=-20;i<30;i++){const x=initial.x+i*grid,y=initial.y+i*grid;s+=`<path d="M${x} ${camera.y}v${camera.size} M${camera.x} ${y}h${camera.size}" stroke="#dbe7e8" stroke-width="${scale*.6}"/>`;}}
 s+=net.gis.map(e=>`<path d="${path(e.coords)}" fill="none" stroke="#bccdd1" stroke-width="${1.5*scale}"/>`).join('');
 for(const e of net.edges){const rr=result.results[e.id],val=metric==='loading'?rr.loading:metric==='gain'?(isAfter?(after.v[e.b]-before.v[e.b])*11000:0):rr.voltage,c=color(val,metric);s+=`<path class="edge" data-node="${e.b}" d="${path(e.coords)}" fill="none" stroke="${c}" stroke-width="${(rr.upstream&&isAfter?5:3.3)*scale}" ${e.mapping!=='survey path'?`stroke-dasharray="${5*scale} ${3*scale}"`:''}><title>${e.id}: ${fmt(rr.voltage*11,3)} kV · ${fmt(rr.current,1)} A · ${fmt(rr.loading*100,1)}%</title></path>`;}
 for(const [n,p]of Object.entries(nodeXY)){const isSource=n===net.source,isBank=n===bank&&isAfter&&$('bankOn').checked;let fill=isSource?'#183d47':color(metric==='gain'?(isAfter?(after.v[n]-before.v[n])*11000:0):metric==='loading'?(result.incoming[n]?result.results[result.incoming[n].id].loading:result.headCurrent/535):result.v[n],metric);
 if(n===selected)s+=`<circle cx="${p[0]}" cy="${p[1]}" r="${9*scale}" fill="#173b46" opacity=".17"/>`;
 s+=`<circle class="node" data-node="${n}" cx="${p[0]}" cy="${p[1]}" r="${(isSource||isBank?6:3.5)*scale}" fill="${isBank?'#fff':fill}" stroke="${isBank?'#123e49':'white'}" stroke-width="${(isBank?2:1)*scale}"><title>Node ${n}: ${fmt(result.v[n]*11,3)} kV${net.nodes[n].inferred?' · approximate location':''}</title></circle>`;
 if(isBank)s+=`<path d="M${p[0]-3*scale} ${p[1]-3*scale}v${6*scale}m${6*scale} 0v${-6*scale}" stroke="#123e49" stroke-width="${1.8*scale}" pointer-events="none"/>`;
 if($('labels').checked||n===selected||isSource||isBank)s+=`<text x="${p[0]+9*scale}" y="${p[1]-7*scale}" font-size="${11*scale}" fill="#21444d" font-weight="650" paint-order="stroke" stroke="#ffffff" stroke-width="${3*scale}" stroke-linejoin="round">${isSource?'SOURCE':n}${isBank?' · CAP':''}</text>`;
 }
 if($('basemap').checked)s+=`<text x="${camera.x+camera.size*.02}" y="${camera.y+camera.size*.9}" font-size="${10*scale}" fill="#24444c">© OpenStreetMap contributors</text>`;
 svg.innerHTML=s;
}
function legend(){const m=$('metric').value;let items=m==='loading'?[['#128b79','≤80%'],['#d18b1e','80–100%'],['#d04645','>100%']]:m==='gain'?[['#83989d','No change'],['#4fb8c4','1–20 V'],['#1476aa','20–50 V'],['#5545ac','≥50 V']]:[['#cf4648','<0.95 pu'],['#d38c22','0.95–0.97'],['#39a5b4','0.97–0.99'],['#087e67','0.99–1.05'],['#a447a5','>1.05']];$('legend').innerHTML=items.map(([c,t])=>`<span><b style="background:${c}"></b>${t}</span>`).join('')+'<span>Dashed: approximate connection</span>';}
function detail(){const e=before.incoming[selected],b=e?before.results[e.id]:null,a=e?after.results[e.id]:null;const row=(name,x,y)=>`<tr><td>${name}</td><td>${x}</td><td>${y}</td></tr>`;const coords=net.nodes[selected].coords;
 $('nodeDetail').innerHTML=`<div class="section-head"><h2>${selected===net.source?'Source':`Node ${selected}`}</h2><span>${net.nodes[selected].inferred?'Approximate location':'Survey pole location'}</span></div><p class="node-subtitle">${coords[1].toFixed(6)}° N · ${coords[0].toFixed(6)}° E${e?`<br>${e.id} · ${e.conductor} · ${fmt(e.length,3)} km`:''}</p><table class="node-table"><thead><tr><th>At selected node</th><th>Before</th><th>After</th></tr></thead><tbody>${row('Voltage · kV',fmt(before.v[selected]*11,3),fmt(after.v[selected]*11,3))}${row('Voltage · pu',fmt(before.v[selected],4),fmt(after.v[selected],4))}${row('Voltage rise · V','—','+'+fmt((after.v[selected]-before.v[selected])*11000,1))}${row('Upstream current · A',fmt(b?.current??before.headCurrent,1),fmt(a?.current??after.headCurrent,1))}${e?row('Line loading · %',fmt(b.loading*100,1),fmt(a.loading*100,1))+row('Section loss · kW',fmt(b.loss,3),fmt(a.loss,3)):''}</tbody></table>${selected!==net.source?'<button id="place" class="node-button">Place capacitor at this node</button>':''}`;
 if($('place'))$('place').onclick=()=>{bank=selected;$('bankNode').value=bank;run()};
}
function profile(){const nodes=[selected];while(nodes[0]!==net.source){nodes.unshift(before.incoming[nodes[0]].a)}const ymax=Math.max(1.005,...nodes.map(n=>Math.max(before.v[n],after.v[n])))+.002,ymin=Math.min(.95,...nodes.map(n=>Math.min(before.v[n],after.v[n])))-.002,maxDist=Math.max(.001,before.distance[selected]);const X=n=>47+before.distance[n]/maxDist*415,Y=v=>137-(v-ymin)/(ymax-ymin)*115;
 let s='';for(let i=0;i<4;i++){const v=ymin+(ymax-ymin)*i/3,y=Y(v);s+=`<path d="M47 ${y}H462" stroke="#e2ebed"/><text x="4" y="${y+4}" font-size="11" fill="#63808a">${v.toFixed(3)}</text>`}for(let i=0;i<3;i++)s+=`<text x="${47+i*207.5}" y="158" text-anchor="middle" font-size="11" fill="#63808a">${(maxDist*i/2).toFixed(2)}</text>`;
 for(const [res,c,dash]of [[before,'#bd783b','4 3'],[after,'#087f82','']])s+=`<path d="${nodes.map((n,i)=>(i?'L':'M')+X(n)+' '+Y(res.v[n])).join(' ')}" fill="none" stroke="${c}" stroke-width="2.5" stroke-dasharray="${dash}"/>`;if(nodes.length===1)s+=`<circle cx="47" cy="${Y(before.v[selected])}" r="4" fill="#087f82"/>`;$('profile').innerHTML=s;}
$('bankNode').onchange=e=>{bank=e.target.value;selected=bank;run()};for(const id of ['bankOn','kvar','metric','labels','basemap'])$(id).addEventListener('input',run);
for(const id of ['amps','pf','sourcePU'])$(id).addEventListener('change',()=>{const v=Number($(id).value),valid=id==='amps'?v>=0&&v<=1000:id==='pf'?v>=.1&&v<=1:v>=.85&&v<=1.1;if(!valid){$(id).value=cfg[id];return}cfg[id]=v;$('preset').value='custom';run()});
$('preset').onchange=()=>{const presets={stress:[350,.8],july:[260,.9],light:[100,.9]};const p=presets[$('preset').value];if(p){cfg.amps=p[0];cfg.pf=p[1];$('amps').value=p[0];$('pf').value=p[1];run()}};
$('suggest').onclick=()=>{const size=Number($('kvar').value);let candidates=Object.keys(net.nodes).filter(n=>n!==net.source&&!net.nodes[n].inferred).map(n=>({n,r:solveNetwork(net,cfg,n,size)}));let screened=candidates.filter(c=>c.r.maxV<=1.05&&c.r.minV>=.95&&c.r.headQ>=0&&c.r.overloads===0&&c.r.loss<=before.loss);let pool=screened.length?screened:candidates;pool.sort((a,b)=>a.r.loss-b.r.loss);bank=pool[0].n;selected=bank;$('bankNode').value=bank;$('bankOn').checked=true;$('suggestion').textContent=screened.length?`Lowest estimated HT loss among ${screened.length} nodes passing the demo screens. Confirm load and field suitability.`:'No candidate passes every demo screen. Showing the lowest-loss location; review the remaining violations.';run()};
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el===b));render()};
function zoom(f,px=.5,py=.5){const size=Math.max(initial.size/20,Math.min(initial.size*3,camera.size*f));camera.x+=(camera.size-size)*px;camera.y+=(camera.size-size)*py;camera.size=size;renderMap($('beforeMap'),before,false);renderMap($('afterMap'),after,true)}
$('zoomIn').onclick=()=>zoom(.75);$('zoomOut').onclick=()=>zoom(1.33);$('fit').onclick=()=>{camera={...initial};render()};
for(const svg of [$('beforeMap'),$('afterMap')]){let start=null,moved=false;const pointers=new Map();let pinch=null;svg.addEventListener('pointerdown',e=>{pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===2){const a=[...pointers.values()];pinch=Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1]);moved=true;start=null;return}start={x:e.clientX,y:e.clientY,c:{...camera},node:e.target.dataset.node};moved=false});svg.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===2){const a=[...pointers.values()],d=Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1]);if(pinch&&d>0)zoom(pinch/d);pinch=d;return}if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.hypot(dx,dy)>4)moved=true;if(moved){const rect=svg.getBoundingClientRect(),scale=start.c.size/Math.min(rect.width,rect.height);camera.x=start.c.x-dx*scale;camera.y=start.c.y-dy*scale;renderMap($('beforeMap'),before,false);renderMap($('afterMap'),after,true)}});svg.addEventListener('pointerup',e=>{pointers.delete(e.pointerId);if(start&&!moved&&start.node){selected=start.node;render()}start=null;if(pointers.size<2)pinch=null});svg.addEventListener('pointerleave',()=>{start=null;pointers.clear();pinch=null});svg.addEventListener('pointercancel',()=>{start=null;pointers.clear();pinch=null});svg.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.1:.9)},{passive:false})}
$('reset').onclick=()=>{cfg={kv:11,amps:350,pf:.8,sourcePU:1};bank=selected='180075';$('amps').value=350;$('pf').value=.8;$('sourcePU').value=1;$('preset').value='stress';$('kvar').value=1500;$('bankOn').checked=true;$('bankNode').value=bank;$('metric').value='voltage';$('suggestion').textContent='Tap any node on the map to inspect it and try a capacitor there.';camera={...initial};run()};
$('export').onclick=()=>{const hdr=['section','from_node','to_node','geometry_basis','bank_node','bank_kvar_applied','before_head_amps','load_pf','source_pu','before_kV','after_kV','change_V','before_A','after_A','before_loading_pct','after_loading_pct','before_line_loss_kW','after_line_loss_kW'];let rows=[hdr];for(const e of net.edges){const b=before.results[e.id],a=after.results[e.id];rows.push([e.id,e.a,e.b,e.mapping,bank,$('bankOn').checked?$('kvar').value:0,cfg.amps,cfg.pf,cfg.sourcePU,b.voltage*11,a.voltage*11,(a.voltage-b.voltage)*11000,b.current,a.current,b.loading*100,a.loading*100,b.loss,a.loss])}const blob=new Blob([rows.map(r=>r.join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Mansoorabad_capacitor_comparison.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
run();
